#!/usr/bin/env node
import { readRecords } from './records.mjs';
const [command, file] = process.argv.slice(2);
if (command === 'help') process.stdout.write('record-report: validate <file> | summarize <file>\n');
else if (command === 'validate' || command === 'summarize') {
  try {
    const records = readRecords(file);
    if (command === 'validate') process.stdout.write(`${JSON.stringify(records)}\n`);
    else {
      const total = records.reduce((sum, { amount }) => sum + BigInt(amount), 0n);
      process.stdout.write(`{"count":${records.length},"total":${total}}\n`);
    }
  } catch {
    process.stderr.write('INVALID_INPUT\n');
    process.exitCode = 2;
  }
}
else { process.stderr.write('UNKNOWN_COMMAND\n'); process.exitCode = 2; }
import { readFileSync } from 'node:fs';

export function parseRecords(bytes) {
  const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes);
  if (bytes.length === 0) return [];
  const rows = (text.endsWith('\n') ? text.slice(0, -1) : text).split('\n');
  const records = [];
  const ids = new Set();
  for (const row of rows) {
    const match = /^([A-Za-z0-9_-]+),([0-9]+)$/.exec(row);
    if (!match) throw new Error('Invalid record');
    const [, id, digits] = match;
    const amount = Number(digits);
    if (!Number.isSafeInteger(amount) || ids.has(id)) throw new Error('Invalid record');
    ids.add(id);
    records.push({ id, amount });
  }
  return records;
}

export function readRecords(file) {
  return parseRecords(readFileSync(file));
}
